// Before & after › Drata (route before-after-drata): what to borrow from Drata, each recommendation as the prototype today
// (V3 on) beside the screen after it, the new screens and the new components. Reads window.PA.DRBA (generated by
// SP/vanta/v4dr/lead/gen.py from each lane's notes.json, mod-zzzz-v4-9drba-data.js) and window.PA.drk (the Drata kit, lane K:
// D.COMPONENTS and D.demo). The after screens are the lanes' own routes (dr-…); this page only shows and opens them.
// Screenshots are served beside the page as dr/cur-<pair>.jpg and dr/aft-<pair>.jpg.
(function () {
  const PA = window.PA; if (!PA || !PA.S) return;
  const { S, M, ROUTE_NAV, h } = PA;
  const { esc, header } = h;
  const ROUTE = "before-after-drata";
  const D = () => PA.DRBA || { groups: [], recs: [], pairs: [], components: [], leave: [], derived: [], conflicts: [], open: [], added: [], checks: [], lanes: [] };
  const KIT = () => PA.drk || null;
  const pairById = (id) => (D().pairs || []).find((p) => p.id === id) || null;
  const recsOf = (p) => [...new Set((p.changes || []).flatMap((c) => (Array.isArray(c.rec) ? c.rec : [c.rec])).filter((n) => Number.isInteger(n)))].sort((a, b) => a - b);

  // ——— Opening a screen: V3 on, WS-X90, the route, then a preview or a click if the pair asks for one ———
  function go(s) {
    if (!s || !s.route) return;
    const spec = { route: s.route, prog: "wsx" };
    if (s.panel && s.panel.kind) spec.open = { kind: s.panel.kind, id: s.panel.id };
    if (PA.v3ba && PA.v3ba.see) PA.v3ba.see(spec);
    else { if (PA.v3 && !PA.v3.on()) PA.v3.set(true); location.hash = s.route; }
    if (s.click || s.scroll) setTimeout(() => {
      const main = document.getElementById("main") || document;
      if (s.scroll) { const t = main.querySelector(s.scroll); if (t) t.scrollIntoView({ block: "center" }); }
      if (s.click) { const t = document.querySelector(s.click); if (t) t.click(); }
    }, 650);
  }
  function open(id, side) {
    const p = pairById(id); if (!p) return;
    go(side === "cur" ? p.current : p.after);
  }
  // An item new in version 24 opens straight at its own route.
  function openAdded(i) { go((D().added || [])[i]); }
  document.addEventListener("click", (e) => {
    const b = e.target.closest("[data-drba-added]"); if (!b) return;
    e.preventDefault(); openAdded(Number(b.dataset.drbaAdded));
  });
  document.addEventListener("click", (e) => {
    const b = e.target.closest("[data-drba-open]"); if (!b) return;
    e.preventDefault(); const [side, id] = String(b.dataset.drbaOpen).split(":"); open(id, side);
  });
  document.addEventListener("click", (e) => {
    const b = e.target.closest("[data-drba-jump]"); if (!b) return;
    e.preventDefault(); const t = document.getElementById(b.dataset.drbaJump); if (t) t.scrollIntoView({ block: "start", behavior: "smooth" });
  });

  // ——— Pieces ———
  const ev = (e) => `<a class="ba-ev" href="${esc(e.u)}" target="_blank" rel="noopener" title="${esc(`${e.t}, image ${e.n}. Local copy: ${e.f}`)}">${esc(e.s || e.t)}</a>`;
  const evs = (list) => (list && list.length ? `<span class="ba-evs">${list.map(ev).join("")}</span>` : "");
  const recTag = (n) => `<span class="drba-rec num" title="${esc((D().recs.find((r) => r.n === n) || {}).title || "")}">${n}</span>`;

  function fig(p, side) {
    const img = side === "cur" ? p.cur : p.aft;
    const cap = side === "cur" ? `<span class="ba-tag">Current</span>${p.new ? "No screen for this today" : "The prototype today, V3 on"}` : `<span class="ba-tag a">After</span>Drata's pattern, drawn our way`;
    const alt = `${p.title}, ${side === "cur" ? "current" : "after"}`;
    const none = side === "cur"
      ? (p.new ? `A new screen. ${p.current && p.current.note ? esc(p.current.note) : "Nothing in the prototype does this today."}` : "The screenshot comes with the publish.")
      : "The screenshot comes with the publish.";
    return `<figure class="ba-fig"><figcaption>${cap}</figcaption>
      ${img ? `<button type="button" class="ba-img" data-modal="v3b-zoom" data-id="${esc(img)}|${esc(alt)}" aria-label="Enlarge ${esc(alt)}"><img src="${esc(img)}" alt="${esc(alt)}" loading="lazy"></button>` : `<div class="ba-none">${none}</div>`}</figure>`;
  }

  function change(c) {
    const recs = (Array.isArray(c.rec) ? c.rec : [c.rec]).filter((n) => Number.isInteger(n));
    return `<li class="ba-dev"><span class="ba-n num" aria-hidden="true">${esc(c.n)}</span><div class="ba-dev-b">
      <div class="ba-dev-t"><b>${esc(c.title || "")}</b><span class="ba-dev-p">${recs.map(recTag).join("")}</span></div>
      <dl class="ba-dl"><dt>After</dt><dd>${esc(c.text || "")}</dd>${c.drata ? `<dt>Drata</dt><dd>${esc(c.drata)}${evs(c.ev)}</dd>` : ""}</dl></div></li>`;
  }

  function pair(p) {
    const n = (p.changes || []).length, recs = recsOf(p);
    const cur = p.current && p.current.route && !p.new;
    return `<section class="ba-pair drba-pair" id="drba-${esc(p.id)}">
      <div class="ba-ph"><div class="ba-ph-t"><h3 tabindex="-1">${esc(p.title)}</h3>
        <div class="facts">${p.new ? `<span>New screen</span>` : ""}<span class="num">${n} ${n === 1 ? "change" : "changes"}</span>${recs.length ? `<span>Recommendations ${recs.join(", ")}</span>` : ""}</div></div>
        <div class="btns">${cur ? `<button type="button" class="btn sm" data-drba-open="cur:${esc(p.id)}">Open current</button>` : ""}${p.after && p.after.route ? `<button type="button" class="btn sm ink" data-drba-open="aft:${esc(p.id)}">Open after</button>` : ""}</div></div>
      <div class="ba-frames">${fig(p, "cur")}${fig(p, "aft")}</div>
      ${n ? `<ol class="ba-devs">${p.changes.map(change).join("")}</ol>` : ""}
    </section>`;
  }

  function components() {
    const kit = KIT(); const notes = D().components || [];
    const list = kit && Array.isArray(kit.COMPONENTS) ? kit.COMPONENTS : [];
    if (!list.length) return `<p class="ba-quiet">The components gallery is still being built.</p>`;
    const used = (id) => notes.filter((c) => c.id === id && c.used).map((c) => c.used);
    return `<div class="drba-comps">${list.map((c) => {
      let demo = "";
      try { demo = kit.demo ? kit.demo(c.id) : ""; } catch (e) { demo = `<p class="ba-quiet">This demo could not draw: ${esc(e.message)}</p>`; }
      const where = [c.where, ...used(c.id)].filter(Boolean);
      return `<article class="drba-comp" id="drba-c-${esc(c.id)}"><div class="drba-comp-h"><h4>${esc(c.name)}</h4><span class="ba-dev-p">${(c.rec || []).map(recTag).join("")}</span></div>
        ${c.what ? `<p class="drba-comp-w">${esc(c.what)}</p>` : ""}
        <div class="drba-demo">${demo}</div>
        <dl class="ba-dl">${where.length ? `<dt>Used</dt><dd>${esc(where.join(" · "))}</dd>` : ""}${c.ledger ? `<dt>Ledger</dt><dd>${esc(c.ledger)}</dd>` : ""}</dl></article>`;
    }).join("")}</div>`;
  }

  function coverage() {
    const d = D();
    const where = (r) => {
      const ps = [...new Set(r.pairs || [])].map(pairById).filter(Boolean);
      if (ps.length) return ps.map((p) => `<a href="#${ROUTE}" data-drba-jump="drba-${esc(p.id)}">${esc(p.title)}</a>`).join(", ");
      const kit = KIT(); const c = kit && (kit.COMPONENTS || []).find((x) => (x.rec || []).includes(r.n));
      return c ? `<a href="#${ROUTE}" data-drba-jump="drba-c-${esc(c.id)}">${esc(c.name)}</a> (component)` : `<span class="ba-quiet">Not drawn yet</span>`;
    };
    return (d.groups || []).map((g) => {
      const rs = (d.recs || []).filter((r) => r.group === g.key); if (!rs.length) return "";
      return `<div class="drba-cov-g"><h4>${esc(g.label)}</h4><table class="drba-cov"><tbody>${rs.map((r) => `<tr><td class="num">${r.n}</td><td title="${esc(r.title)}">${esc(r.title)}</td><td>${where(r)}</td></tr>`).join("")}</tbody></table></div>`;
    }).join("");
  }

  const LANE = { K: "Components", A: "Controls", B: "Evidence", C: "Sources", F: "Checks" };
  function addedList() {
    const xs = D().added || []; if (!xs.length) return "";
    return `<section class="drba-new" id="drba-new"><div class="drba-new-h"><h3 class="ba-sub">New in version 24</h3><span class="num">${xs.length}</span></div>
      <p class="ba-lede drba-small">Version 23's Not done list, built. Each opens the screen where it shows.</p>
      <ul class="drba-new-l">${xs.map((a, i) => {
        const p = a.pair ? pairById(a.pair) : null;
        return `<li><span class="drba-new-k">${esc(LANE[a.lane] || a.lane)}</span><span class="drba-new-t">${esc(a.text)}${p ? ` <a href="#${ROUTE}" data-drba-jump="drba-${esc(p.id)}">${esc(p.title)}</a>` : ""}</span><button type="button" class="btn sm" data-drba-added="${i}">Open</button></li>`;
      }).join("")}</ul></section>`;
  }

  function draw() {
    const d = D(), ps = d.pairs || [];
    const tabs = S["before-after"] ? (() => { const t = document.createElement("template"); t.innerHTML = S["before-after"](); const el = t.content.querySelector(".ba-tabs"); if (el) el.querySelectorAll('[role="tab"]').forEach((x) => { const sel = x.dataset.go === ROUTE; x.setAttribute("aria-selected", String(sel)); x.classList.toggle("on", sel); }); return el ? el.outerHTML : ""; })() : "";
    const nNew = ps.filter((p) => p.new).length, nComp = ((KIT() || {}).COMPONENTS || []).length;
    const nCh = ps.reduce((a, p) => a + (p.changes || []).length, 0);
    const groups = (d.groups || []).map((g) => ({ ...g, ps: ps.filter((p) => p.group === g.key) })).filter((g) => g.ps.length);
    const facts = `<span class="num">${ps.length - nNew} screens compared</span><span class="num">${nNew} new screens</span><span class="num">${nComp} new components</span><span class="num">${nCh} changes</span>`;
    return `<div class="main ba drba">${header("Before, v1, v2 and V3", facts, "")}${tabs}
      <section class="drba-hero"><h2>Drata: what to borrow</h2>
        <p class="ba-lede">Drata is strongest on the line from control to evidence to automated check: every number on a control traces back to something you can open. Each block below is one screen. <b>Current</b> is the prototype today with V3 on. <b>After</b> is the same screen with Drata's patterns applied, drawn our way and working: press Open after to use it. The numbered changes say what changed, what Drata does, and link the Drata help-center article it comes from.</p>
        <p class="ba-lede drba-small">Nothing here changes the prototype. The after screens are extra pages; V3 and v2 are as they were.</p>
        <nav class="drba-jump" aria-label="On this page">${(d.added || []).length ? `<a href="#${ROUTE}" data-drba-jump="drba-new">New in version 24 <span class="num">${d.added.length}</span></a>` : ""}${groups.map((g) => `<a href="#${ROUTE}" data-drba-jump="drba-g-${esc(g.key)}">${esc(g.label)} <span class="num">${g.ps.length}</span></a>`).join("")}<a href="#${ROUTE}" data-drba-jump="drba-components">New components <span class="num">${nComp}</span></a><a href="#${ROUTE}" data-drba-jump="drba-all">All 28 recommendations</a><a href="#${ROUTE}" data-drba-jump="drba-leave">Leave behind</a></nav>
      </section>
      ${addedList()}
      ${groups.map((g) => `<h3 class="ba-sub" id="drba-g-${esc(g.key)}">${esc(g.label)}</h3>${g.ps.map(pair).join("")}`).join("")}
      <h3 class="ba-sub" id="drba-components">New components</h3>
      <p class="ba-lede">The pieces the after screens are built from, each live. ${KIT() ? `<span class="btn sm" data-go="dr-components" role="link" tabindex="0">Open the gallery</span>` : ""}</p>
      ${components()}
      <h3 class="ba-sub" id="drba-all">All 28 recommendations, and where each is shown</h3>
      <div class="drba-cov-w">${coverage()}</div>
      <h3 class="ba-sub" id="drba-leave">Leave behind</h3>
      <ul class="drba-leave">${(d.leave || []).map((x) => `<li>${esc(x)}</li>`).join("")}</ul>
      ${(d.conflicts || []).length ? `<details class="ba-hist"><summary>Where a Drata pattern met one of your rules <span class="num">${d.conflicts.length}</span></summary><ul class="drba-list">${d.conflicts.map((x) => `<li>${esc(x)}</li>`).join("")}</ul></details>` : ""}
      ${(d.derived || []).length ? `<details class="ba-hist"><summary>Values derived because the prototype lacks them <span class="num">${d.derived.length}</span></summary><ul class="drba-list">${d.derived.map((x) => `<li>${esc(x)}</li>`).join("")}</ul></details>` : ""}
      ${(d.open || []).length ? `<details class="ba-hist"><summary>Not done <span class="num">${d.open.length}</span></summary><ul class="drba-list">${d.open.map((x) => `<li>${esc(x)}</li>`).join("")}</ul></details>` : ""}
      ${(d.checks || []).length ? `<div class="ba-method"><h3>How it was checked</h3>${d.checks.map((c) => `<p>${esc(c)}</p>`).join("")}</div>` : ""}
    </div>`;
  }

  ROUTE_NAV[ROUTE] = "before-after";
  const g = function () { return draw(); }; g.__v2c = true; S[ROUTE] = g;
  // The tab joins the Before & after strip; mod-zz-compare.js puts it first.
  if (PA.BA2 && Array.isArray(PA.BA2.groups) && !PA.BA2.groups.some((x) => x.key === "drata")) PA.BA2.groups.unshift({ key: "drata", short: "Drata", label: "Drata: what to borrow", intro: "" });
  // The overview leads with a card that opens this tab.
  const base = S["before-after"];
  if (base && !base.__drba) {
    const wrapped = function () {
      const html = base.apply(this, arguments);
      const ps = D().pairs || [];
      const card = `<div class="ba-v3call drba-call"><div><b>What to borrow from Drata.</b> ${ps.length ? `${ps.length} screens, each as it is today beside the screen after Drata's pattern, plus the new components.` : "Each screen as it is today beside the screen after Drata's pattern, plus the new components."}</div><span class="btn ink" data-go="${ROUTE}" role="link" tabindex="0">Open Drata</span></div>`;
      return html.replace(/(<div class="ba-tabs"[\s\S]*?<\/div>)/, `$1${card}`);
    };
    Object.keys(base).forEach((k) => { wrapped[k] = base[k]; });
    wrapped.__drba = true; S["before-after"] = wrapped;
  }
  PA.drba = { open, openAdded, count: () => (D().pairs || []).length };
})();
